contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single public test function driving the sequence
    // params:
    // firstDeposit - amount of wei to deposit initially
    // firstUnlock - initial unlock time passed to first Put
    // secondDeposit - amount of wei for second Put
    // secondUnlock - second unlock time which may be <= firstUnlock
    function run(uint firstDeposit, uint firstUnlock, uint secondDeposit, uint secondUnlock) public payable {
        // need enough balance in this contract to send deposits
        require(address(this).balance >= firstDeposit + secondDeposit, "insufficient balance for test");

        // first Put: set up an account with some unlock time
        c.Put{value: firstDeposit}(firstUnlock);

        // second Put: attempt to set a (possibly non-increasing) unlockTime
        // On P this must succeed (no require on non-increase); on M it may revert when secondUnlock <= previous acc.unlockTime
        bool ok;
        (ok, ) = address(c).call{value: secondDeposit}(abi.encodeWithSignature("Put(uint256)", secondUnlock));

        // The distinguishing assertion: Put should not be rejected solely because the new unlock time is not greater than the old one.
        // We express that by asserting that either the second call succeeded (ok==true) OR the new recorded unlockTime in the contract is strictly greater than firstUnlock
        // If the second call reverted due to requiring increase, then ok==false and unlockTime will remain > = firstUnlock, violating the expectation that non-increasing puts are allowed.

        // Read observed unlockTime from the public mapping Acc for this contract's address
        uint observedUnlock = c.Acc(address(this)).unlockTime;

        // Assert the general rule: either second Put succeeded, or the contract's unlockTime is now strictly greater than the previous value
        // On original P: second Put should succeed (ok==true) even when secondUnlock <= firstUnlock, so the left disjunct holds.
        // On mutant M: second Put will revert when secondUnlock <= previous unlock, making ok==false while observedUnlock will not have increased, so this assertion can fail.
        assert(ok || (observedUnlock > firstUnlock));
    }

    // allow the test contract to receive ETH for performing deposits
    receive() external payable {}
}

