pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters:
    // - uint96 deposit: amount of wei to send in Put (kept bounded but wide)
    // - uint256 providedUnlock: the _unlockTime argument passed to Put (may be in future)
    // - uint256 extraWarp: how far to warp time before calling Put, to allow future times
    function testFuzz_property(uint96 deposit, uint256 providedUnlock, uint256 extraWarp) public {
        // Keep deposit in a sensible range but wide (not zero to ensure a deposit occurs)
        deposit = uint96(bound(deposit, 1, 10 ether));
        // Keep extraWarp modest but allow future times
        extraWarp = bound(extraWarp, 0, 100000);

        // Choose sender
        address sender = address(0xBEEF);
        vm.deal(sender, deposit);

        // Warp forward a bit to make block.timestamp nonzero and allow providedUnlock to be relative
        vm.warp(block.timestamp + extraWarp);

        // Construct a provided unlock time that may be in the future relative to current block
        uint256 _unlockTime = providedUnlock;
        // Allow fuzz to pick arbitrary value; no tight restriction so mutant can be exposed

        // Execute Put from sender with value
        vm.prank(sender);
        c.Put{value: deposit}(_unlockTime);

        // The general invariant (reference holds): after Put returns, the stored unlockTime for sender
        // must be >= block.timestamp (the current time when Put completed). This is because the reference
        // sets unlockTime = max(_unlockTime, block.timestamp). The mutant that unconditionally sets
        // unlockTime = block.timestamp will still satisfy >= block.timestamp here, but the important
        // distinguishing rule is that if caller previously had a later unlockTime (in future), Put must
        // NOT decrease it below that later time. We therefore exercise by first setting a future unlock
        // and then calling Put with a providedUnlock in the future to ensure reference preserves the
        // maximum while mutant may reduce it.

        // To realize the distinguishing input, we now perform a sequence: (1) set a large future unlock by
        // calling Put with an explicit huge providedUnlock (simulate previous state), then (2) call Put
        // again with a smaller providedUnlock so that the reference keeps the larger unlock, but mutant
        // would reset to now. We implement that by performing an additional call sequence.

        // Step 1: create prior state with very large unlockTime using a different deposit
        uint96 deposit2 = uint96(bound(uint256(deposit) + 1, 1, 20 ether));
        vm.deal(sender, deposit2);
        // choose a far future unlock
        uint256 farFuture = block.timestamp + 10000;
        vm.prank(sender);
        c.Put{value: deposit2}(farFuture);

        // Read stored unlock after step1; it should be >= farFuture
        uint256 storedAfterStep1 = c.Acc(sender).unlockTime;

        // Now call Put again with the original deposit and a providedUnlock that is less than storedAfterStep1
        // We ensure providedUnlockLess < storedAfterStep1 by bounding it
        uint256 providedLess = storedAfterStep1 > 0 ? storedAfterStep1 - 1 : 0;
        vm.deal(sender, deposit);
        vm.prank(sender);
        c.Put{value: deposit}(providedLess);

        // SINGLE ASSERTION: the reference implementation preserves a previously set later unlockTime,
        // so after the second Put the stored unlockTime must still be >= storedAfterStep1.
        // The mutant that unconditionally sets unlockTime = block.timestamp can make the stored value
        // smaller than storedAfterStep1 for some inputs, so this assertion will fail on the mutant.
        uint256 storedFinal = c.Acc(sender).unlockTime;
        assertTrue(storedFinal >= storedAfterStep1);
    }
}

